def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D'
    if n == 2:
        return 'D'
    if n == 3:
        return 'D'
    if n == 4:
        return 'D'
    # n >= 5
    opp_first5 = [history[i][1] for i in range(5)]
    if all(a == 'C' for a in opp_first5):
        return 'D'
    if n == 5:
        return 'C'
    if n == 99:
        return 'D'
    last_my, last_opp = history[-1]
    if last_opp == 'C':
        return 'C'
    else:
        if last_my == 'C':
            if n >= 2 and history[-2][0] == 'C' and history[-2][1] == 'D':
                return 'D'
            return 'C'
        else:
            return 'D' if rng.random() < 0.7 else 'C'
